// Reviewed wire contracts. Runtime implementations remain authoritative.
export const ref = name => ({ $ref: `#/components/schemas/${name}` })
export const str = (maxLength, description) => ({ type: 'string', ...(maxLength ? { maxLength } : {}), ...(description ? { description } : {}) })
export const int = (minimum = 0, maximum) => ({ type: 'integer', minimum, ...(maximum === undefined ? {} : { maximum }) })
export const bool = { type: 'boolean' }
export const lit = value => ({ const: value, type: typeof value })
export const choice = (...values) => ({ type: 'string', enum: values })
export const array = (items, maxItems) => ({ type: 'array', items, ...(maxItems ? { maxItems } : {}) })
export const nullable = schema => ({ anyOf: [schema, { type: 'null' }] })
export const obj = (properties = {}, required = [], extra = {}) => ({ type: 'object', properties, additionalProperties: false, ...(required.length ? { required } : {}), ...extra })
export const result = (properties, required = Object.keys(properties)) => obj(properties, required, { additionalProperties: true })
export const id = { type: 'string', minLength: 1, maxLength: 200, description: 'Opaque server-issued ID; never infer authority from it.' }
export const requestId = { type: 'string', pattern: '^[A-Za-z0-9_-]{1,100}$' }
export const sha = { type: 'string', pattern: '^[a-f0-9]{40}$' }
export const hash = { type: 'string', pattern: '^[a-f0-9]{64}$' }
export const repository = { type: 'string', pattern: '^[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+$', maxLength: 200 }
export const role = { type: 'string', pattern: '^[a-z][a-z0-9-]{0,31}$' }
export const visibility = choice('public', 'private')
export const harness = choice('flybot', 'codex', 'claude-agent')
export const page = { after: id, limit: int(1, 100) }
export const sourcePage = { offset: int(), limit: int(1, 16000), expectedSha256: hash }
const json = ref('JsonValue')
const map = schema => ({ type: 'object', additionalProperties: schema })
const record = (properties, required = []) => obj(properties, required, { additionalProperties: true })
